const defaultProfile:Profile={name:"Tobi Monilari",headline:"IT Support & Cloud Engineer",phone:"+1 343 987 1884",email:"tobimonilari@gmail.com",address:"Ottawa, Canada",linkedin:"",summary:"IT professional with over 8 years of experience in Identity & Access Management, Microsoft 365 administration, cloud solutions, endpoint management, and enterprise technical support.",skills:"Identity & Access Management, Active Directory, Microsoft Entra ID, access provisioning, security groups, Microsoft 365, Exchange Online, Teams, SharePoint, Intune, KACE, Jamf, Microsoft Azure, Azure AD Connect, hybrid identity, Conditional Access, MFA, SSO, Jira, ServiceNow, Technical Support, SaaS Support, Incident Resolution",experience:"IT Support Engineer — Service Management Group, Kansas City, USA | Jul 2022–Present\n• Oversee IAM in Active Directory and Microsoft Entra ID, including provisioning, access rights and security groups.\n• Manage Microsoft 365 across Exchange Online, Teams, SharePoint and licensing.\n• Administer Intune, KACE and Jamf for Windows, macOS and mobile devices.\n• Implement compliance, patching and software-deployment policies.\n• Resolve authentication, access and device incidents and collaborate across teams.\n\nTechnical Support Representative — Voxloud, Italy | Jun 2021–Jul 2022\n• Provided technical support through calls and live chat and diagnosed root causes.\n• Documented resolutions, improved knowledge content, standardized support processes and created LMS training.\n\nSupport Agent — Crossover for Work, Remote, USA | Jul 2019–Feb 2021\n• Delivered first-contact SaaS support, managed tickets, collaborated across teams and worked a 24/7 shift model.\n\nCloud Support Engineer — Tek Experts | Apr 2018–Jul 2019\n• Troubleshot Azure AD authentication, authorization, MFA, Conditional Access and SSO issues.\n• Guided Azure IAM deployment, configuration, governance and security practices.\n• Investigated identity incidents with diagnostic tools, Azure logs and Microsoft internal resources.\n• Collaborated with Microsoft product engineering on escalations and supported Azure AD Connect hybrid identity.\n\nInformation Technology Officer — Marine Platform Limited | Dec 2015–Mar 2018\n• Installed and configured hardware, software, systems, networks, printers and scanners.\n• Planned maintenance upgrades, resolved faults and maintained licence and compliance records.",education:"Master’s in Information Technology | 2016–2018\nB.Sc. (Hons), Pure and Applied Mathematics | 2008–2014",certifications:["Microsoft 365 Certified: Administrator Expert","Microsoft Certified: Identity and Access Administrator Associate","Microsoft Certified: Azure Fundamentals"]};
